-- Referential, uniqueness, validation, and lookup constraints for 01_create_tables.sql.

ALTER TABLE users ADD CONSTRAINT users_username_uq UNIQUE (username);
ALTER TABLE users ADD CONSTRAINT users_role_ck CHECK (user_role IN ('STUDENT', 'TEACHER'));
ALTER TABLE class_slots ADD CONSTRAINT slots_name_uq UNIQUE (name);
ALTER TABLE class_slots ADD CONSTRAINT slots_teacher_fk FOREIGN KEY (teacher_id) REFERENCES teacher_profiles (teacher_id);
ALTER TABLE teacher_profiles ADD CONSTRAINT teachers_user_uq UNIQUE (user_id);
ALTER TABLE teacher_profiles ADD CONSTRAINT teachers_user_fk FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE;
ALTER TABLE student_profiles ADD CONSTRAINT students_user_uq UNIQUE (user_id);
ALTER TABLE student_profiles ADD CONSTRAINT students_reg_uq UNIQUE (registration_no);
ALTER TABLE student_profiles ADD CONSTRAINT students_sem_ck CHECK (semester BETWEEN 1 AND 12);
ALTER TABLE student_profiles ADD CONSTRAINT students_user_fk FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE;
ALTER TABLE student_profiles ADD CONSTRAINT students_slot_fk FOREIGN KEY (active_slot_id) REFERENCES class_slots (slot_id);
ALTER TABLE courses ADD CONSTRAINT courses_code_uq UNIQUE (code);
ALTER TABLE courses ADD CONSTRAINT courses_sem_ck CHECK (semester BETWEEN 1 AND 12);
ALTER TABLE courses ADD CONSTRAINT courses_teacher_fk FOREIGN KEY (teacher_id) REFERENCES teacher_profiles (teacher_id);
ALTER TABLE course_slots ADD CONSTRAINT course_slots_pair_uq UNIQUE (course_id, slot_id);
ALTER TABLE course_slots ADD CONSTRAINT course_slots_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE;
ALTER TABLE course_slots ADD CONSTRAINT course_slots_slot_fk FOREIGN KEY (slot_id) REFERENCES class_slots (slot_id) ON DELETE CASCADE;
ALTER TABLE enrollments ADD CONSTRAINT enroll_student_course_uq UNIQUE (student_id, course_id);
ALTER TABLE enrollments ADD CONSTRAINT enroll_student_fk FOREIGN KEY (student_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE enrollments ADD CONSTRAINT enroll_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE;
ALTER TABLE enrollments ADD CONSTRAINT enroll_slot_fk FOREIGN KEY (slot_id) REFERENCES class_slots (slot_id);
ALTER TABLE assessments ADD CONSTRAINT assess_course_name_uq UNIQUE (course_id, name);
ALTER TABLE assessments ADD CONSTRAINT assess_score_ck CHECK (max_score > 0 AND weight BETWEEN 0 AND 1);
ALTER TABLE assessments ADD CONSTRAINT assess_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE;
ALTER TABLE marks ADD CONSTRAINT marks_student_assess_uq UNIQUE (student_id, assessment_id);
ALTER TABLE marks ADD CONSTRAINT marks_score_ck CHECK (score >= 0);
ALTER TABLE marks ADD CONSTRAINT marks_source_ck CHECK (mark_source IN ('FACULTY', 'APPROVED_FALLBACK'));
ALTER TABLE marks ADD CONSTRAINT marks_student_fk FOREIGN KEY (student_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE marks ADD CONSTRAINT marks_assess_fk FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE;
ALTER TABLE marks ADD CONSTRAINT marks_entered_fk FOREIGN KEY (entered_by_user_id) REFERENCES users (user_id) ON DELETE SET NULL;
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_status_ck CHECK (submission_status IN ('PENDING', 'APPROVED', 'REJECTED'));
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_outlier_ck CHECK (is_outlier IN (0, 1));
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_score_ck CHECK (score >= 0);
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_peers_ck CHECK (peer_scores_json IS JSON);
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_student_fk FOREIGN KEY (student_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE mark_submissions ADD CONSTRAINT submissions_assess_fk FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE;
ALTER TABLE mark_verifications ADD CONSTRAINT verifications_submission_uq UNIQUE (submission_id);
ALTER TABLE mark_verifications ADD CONSTRAINT verifications_decision_ck CHECK (decision IN ('APPROVED', 'REJECTED'));
ALTER TABLE mark_verifications ADD CONSTRAINT verifications_submission_fk FOREIGN KEY (submission_id) REFERENCES mark_submissions (submission_id) ON DELETE CASCADE;
ALTER TABLE mark_verifications ADD CONSTRAINT verifications_reviewer_fk FOREIGN KEY (reviewer_id) REFERENCES users (user_id);
ALTER TABLE attendance ADD CONSTRAINT attendance_student_course_date_uq UNIQUE (student_id, course_id, attendance_date);
ALTER TABLE attendance ADD CONSTRAINT attendance_present_ck CHECK (present IN (0, 1));
ALTER TABLE attendance ADD CONSTRAINT attendance_student_fk FOREIGN KEY (student_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE attendance ADD CONSTRAINT attendance_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE;
ALTER TABLE study_matches ADD CONSTRAINT matches_pair_course_uq UNIQUE (requester_id, peer_id, course_id);
ALTER TABLE study_matches ADD CONSTRAINT matches_status_ck CHECK (match_status IN ('REQUESTED', 'ACCEPTED', 'DECLINED', 'COMPLETED'));
ALTER TABLE study_matches ADD CONSTRAINT matches_requester_fk FOREIGN KEY (requester_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE study_matches ADD CONSTRAINT matches_peer_fk FOREIGN KEY (peer_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE study_matches ADD CONSTRAINT matches_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE;
ALTER TABLE guidance_alerts ADD CONSTRAINT alerts_status_ck CHECK (alert_status IN ('OPEN', 'SENT', 'ACKNOWLEDGED', 'RESOLVED'));
ALTER TABLE guidance_alerts ADD CONSTRAINT alerts_student_fk FOREIGN KEY (student_id) REFERENCES student_profiles (student_id) ON DELETE CASCADE;
ALTER TABLE guidance_alerts ADD CONSTRAINT alerts_teacher_fk FOREIGN KEY (teacher_user_id) REFERENCES users (user_id);
ALTER TABLE guidance_alerts ADD CONSTRAINT alerts_course_fk FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE SET NULL;
ALTER TABLE mark_audit ADD CONSTRAINT mark_audit_action_ck CHECK (action_type IN ('UPDATE'));
ALTER TABLE mark_audit ADD CONSTRAINT mark_audit_mark_fk FOREIGN KEY (mark_id) REFERENCES marks (mark_id) ON DELETE CASCADE;
ALTER TABLE mark_audit ADD CONSTRAINT mark_audit_actor_fk FOREIGN KEY (changed_by_user_id) REFERENCES users (user_id) ON DELETE SET NULL;

CREATE INDEX users_role_ix ON users (user_role);
CREATE INDEX students_slot_ix ON student_profiles (active_slot_id);
CREATE INDEX courses_teacher_ix ON courses (teacher_id);
CREATE INDEX slots_teacher_ix ON class_slots (teacher_id);
CREATE INDEX enroll_course_slot_ix ON enrollments (course_id, slot_id);
CREATE INDEX assess_course_ix ON assessments (course_id);
CREATE INDEX marks_assessment_ix ON marks (assessment_id);
CREATE INDEX submissions_status_date_ix ON mark_submissions (submission_status, created_at);
CREATE INDEX attendance_course_date_ix ON attendance (course_id, attendance_date);
CREATE INDEX matches_peer_status_ix ON study_matches (peer_id, match_status);
CREATE INDEX alerts_student_status_ix ON guidance_alerts (student_id, alert_status);
